def to_ternary(num):
    result = ''
    while num:
        result += str(num % 3)
        num //= 3
    return result[::-1]

for N in range(3, 100)[::-1]:
    R = to_ternary(N)
    if N % 3 == 0:
        R += R[-2:]
    else:
        R += to_ternary((N % 3) * 3)
    R = int(R, 3)
    if R <= 150:
        print(N)
        break

